package com.smritisathi.app;
import android.content.*;import android.os.*;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.core.*;import com.smritisathi.app.games.*;import com.smritisathi.app.progress.*;import com.smritisathi.app.reminders.*;import com.smritisathi.app.voice.*;import com.smritisathi.app.memory.*;import java.text.*;import java.util.*;
public class PatientDashboardActivity extends BaseActivity {String token,id,name;String selected="MemoryMatch"; TextView reminder; @Override public void onCreate(Bundle b){super.onCreate(b);token=Session.token(this);id=Session.id(this);name=Session.name(this); build(); loadReminder(); SyncManager.register(this);} void build(){header(greeting()+", "+name);root.addView(UI.text(this,"How are you feeling today?")); Button game=UI.button(this,"🧠 Play Today's Game");root.addView(game);game.setOnClickListener(v->{if(selected.equals("MemoryMatch"))startActivity(new Intent(this,MemoryMatchActivity.class));else if(selected.equals("ObjectRecall"))startActivity(new Intent(this,ObjectRecallActivity.class));else startActivity(new Intent(this,PatternRecognitionActivity.class));});selected=new String[]{"MemoryMatch","ObjectRecall","PatternRecognition"}[new Random().nextInt(3)];root.addView(UI.text(this,"Today's game: "+selected)); reminder=UI.card(this,"Loading next reminder...");root.addView(reminder);Button rem=UI.button(this,"⏰ Daily Reminders");root.addView(rem);rem.setOnClickListener(v->startActivity(new Intent(this,ReminderActivity.class)));Button moments=UI.button(this,"📸 Memory Lane — Family Moments");root.addView(moments);moments.setOnClickListener(v->startActivity(new Intent(this,MemoryMomentsActivity.class)));Button voice=UI.button(this,"🗣 Talk to Sathi");root.addView(voice);voice.setOnClickListener(v->startActivity(new Intent(this,TalkToSathiActivity.class)));Button progress=UI.button(this,"📊 My Progress & Badges");root.addView(progress);progress.setOnClickListener(v->startActivity(new Intent(this,ProgressActivity.class)));Button logout=UI.button(this,"Log out");root.addView(logout);logout.setOnClickListener(v->{Session.clear(this);startActivity(new Intent(this,com.smritisathi.app.auth.LoginActivity.class));finish();});offlineBanner();}
String greeting(){int h=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);return h<12?"Good Morning":h<17?"Good Afternoon":"Good Evening";}void loadReminder(){if(id.isEmpty())return;ApiClient.request("GET","/reminders/patient/"+id,token,null,(ok,d,e)->{if(ok&&d.has("data")&&d.getAsJsonArray("data").size()>0){JsonObject r=d.getAsJsonArray("data").get(0).getAsJsonObject();reminder.setText("Next Reminder\n"+r.get("title").getAsString()+"\n"+r.get("scheduledTime").getAsString());}else reminder.setText("No upcoming reminders for today. Relax and enjoy!");});}}
